package stonytark.cinemarr.server;import net.minecraft.commands.Commands;import net.minecraft.network.chat.Component;import net.minecraftforge.common.MinecraftForge;import net.minecraftforge.event.RegisterCommandsEvent;import net.minecraftforge.eventbus.api.SubscribeEvent;import stonytark.cinemarr.core.platform.CinemarrSettings;
public final class CinemarrCommands{private static final CinemarrCommands INSTANCE=new CinemarrCommands();public static void register(){MinecraftForge.EVENT_BUS.register(INSTANCE);}@SubscribeEvent public void commands(RegisterCommandsEvent event){event.getDispatcher().register(Commands.literal("cinemarr").executes(c->status(c.getSource())).then(Commands.literal("status").executes(c->status(c.getSource()))).then(Commands.literal("diagnostics").requires(s->s.hasPermission(CinemarrSettings.operatorPermissionLevel())).executes(c->{c.getSource().sendSuccess(()->Component.literal(CinemarrServer.instance().videoDiagnostics()),false);return 1;})));}private static int status(net.minecraft.commands.CommandSourceStack source){source.sendSuccess(()->Component.literal(CinemarrServer.instance().videoStatus()),false);return 1;}}
